  } catch {
    error(400, "Invalid reporting period");
  }
  const category = url.searchParams.get("category") ?? "members";
  const selected = rankingCategories.find(
    (option) => option.id === category,
  )?.id;
  if (!selected) error(400, "Invalid ranking category");
  const origin = (
    process.env.EXPOSED_API_ORIGIN || "http://127.0.0.1:6999"
  ).replace(/\/$/, "");
  try {
    return {
      period,
      selected,
      rankings: await loadRankings(fetch, request.signal, origin, period),
      error: null,
    };
  } catch {
    return {
      period,
      selected,
      rankings: null,
      error: "Rankings couldn’t load. Try again.",
    };
  }
}) satisfies PageServerLoad;
<script lang="ts">
  import PeriodSelector from "../../PeriodSelector.svelte";
  import { page, navigating } from "$app/state";
  import AppShell from "../../AppShell.svelte";
  import {
    ViewLinks,
    ViewLink,
    ContentChange,
    RankingList,
    Notice,
  } from "../../lib/ui";
  import {
    rankingCategories,
    rankingRows,
    type RankingCategory,
  } from "../../lib/rankings";
  import type { PageData } from "./$types";
  let { data }: { data: PageData } = $props();
  const selected = $derived(data.selected);
  function categoryHref(category: RankingCategory) {
    const url = new URL(page.url.href);
    url.searchParams.set("category", category);
    url.searchParams.set("period", data.period);
    return url.pathname + url.search;
  }
  const rows = $derived(
    data.rankings ? rankingRows(data.rankings, selected) : [],
  );
</script>

<svelte:head><title>Rankings | Exposed</title></svelte:head>
<AppShell target="rankings" current="rankings">
  <main id="rankings" tabindex="-1" aria-busy={Boolean(navigating.to)}>
    {#if navigating.to && navigating.to.url.pathname !== page.url.pathname}<h1>
        Rankings
      </h1>
    {:else if data.rankings}
      <h1>Rankings</h1>
      <div class="toolbar">
