  }
  [data-accent="neutral"] {
    --row-accent: var(--muted);
  }
  .rank {
    color: var(--muted);
    font-size: var(--text-small);
    padding-top: 2px;
    font-variant-numeric: tabular-nums;
  }
  .identity {
    grid-column: 2 / -1;
    display: flex;
    flex-direction: column;
    gap: var(--space-1);
    min-width: 0;
  }
  a,
  .name {
    color: var(--text);
    font-size: var(--text-body);
    font-weight: 600;
    overflow-wrap: anywhere;
    text-decoration: none;
  }
  a:hover {
    text-decoration: underline;
  }
  .context,
  .incomplete {
    color: var(--muted);
    font-size: var(--text-small);
  }
  .bar-track {
    grid-column: 2;
